script.setup:
// A mix of two examples: opentype.js letters (Type particles) and a simplex-noise flow field (Flow field).
// The wind scatters the letters into streams along the field (its curl, so they swirl rather than pile up); when it drops, the particles find
// their way back into the word. Trails come from the flow-field example's fading half-float buffer.
const mod = await ctx.utils.import("https://esm.sh/opentype.js@1.3.4");
const opentype = mod.default ?? mod;
const { createNoise3D } = await ctx.utils.import("https://esm.sh/simplex-noise@4.0.3");
const font = opentype.parse(await (await fetch(ctx.assets["Bungee-Regular.ttf"])).arrayBuffer());
const WORDS = ["SILJANGNIM", "REMIX", "OPEN SOURCE"];
const N = 14000;
// Glyph outlines → N evenly spaced points, fitted to the canvas (uv, y up).
const sample = (text, w, h) => {
  const segs = [];
  let cur = [0, 0], start = [0, 0];
  for (const c of font.getPath(text, 0, 0, 100).commands) {
    if (c.type === "M") { cur = [c.x, c.y]; start = cur; }
    else if (c.type === "L") { segs.push([cur, [c.x, c.y]]); cur = [c.x, c.y]; }
    else if (c.type === "Q" || c.type === "C") {
      let prev = cur;
      for (let k = 1; k <= 10; k++) {
        const t = k / 10, m = 1 - t;
        const p = c.type === "Q"
          ? [m * m * cur[0] + 2 * m * t * c.x1 + t * t * c.x, m * m * cur[1] + 2 * m * t * c.y1 + t * t * c.y]
          : [m ** 3 * cur[0] + 3 * m * m * t * c.x1 + 3 * m * t * t * c.x2 + t ** 3 * c.x, m ** 3 * cur[1] + 3 * m * m * t * c.y1 + 3 * m * t * t * c.y2 + t ** 3 * c.y];
        segs.push([prev, p]); prev = p;
      }
      cur = [c.x, c.y];
    } else if (c.type === "Z") { segs.push([cur, start]); cur = start; }
  }
  const lengths = segs.map(([a, b]) => Math.hypot(b[0] - a[0], b[1] - a[1]));
  const total = lengths.reduce((x, y) => x + y, 0);
  const pts = new Float32Array(N * 2);
  let si = 0, acc = 0;
  for (let i = 0; i < N; i++) {
    const d = (i / N) * total;
    while (si < segs.length - 1 && acc + lengths[si] < d) acc += lengths[si++];
    const [a, b] = segs[si], f = lengths[si] ? (d - acc) / lengths[si] : 0;
    pts[i * 2] = a[0] + (b[0] - a[0]) * f; pts[i * 2 + 1] = a[1] + (b[1] - a[1]) * f;
  }
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (let i = 0; i < N; i++) { x0 = Math.min(x0, pts[i * 2]); x1 = Math.max(x1, pts[i * 2]); y0 = Math.min(y0, pts[i * 2 + 1]); y1 = Math.max(y1, pts[i * 2 + 1]); }
  const aspect = w / h, scale = Math.min(0.86 * aspect / (x1 - x0), 0.42 / (y1 - y0));
  for (let i = 0; i < N; i++) {
    pts[i * 2] = 0.5 + ((pts[i * 2] - (x0 + x1) / 2) * scale) / aspect;
    pts[i * 2 + 1] = 0.5 - (pts[i * 2 + 1] - (y0 + y1) / 2) * scale;
  }
  return pts;
};
const pos = new Float32Array(N * 3); // x, y, speed
for (let i = 0; i < N; i++) { pos[i * 3] = Math.random(); pos[i * 3 + 1] = Math.random(); }
const gl = ctx.gl;
gl.getExtension("EXT_color_buffer_float");
const vao = gl.createVertexArray(), buffer = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 12, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 1, gl.FLOAT, false, 12, 8);
gl.bindVertexArray(null);
Object.assign(ctx.state, {
  WORDS, N, sample, pos, vel: new Float32Array(N * 2), vao, buffer, word: -1, targets: null, size: [0, 0],
  noise: createNoise3D(), trails: null, wind: 1,
  fade: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, '#version 300 es\nprecision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_prev; uniform float u_fade;\nvoid main(){ outColor = vec4(texture(u_prev, v_uv).rgb * u_fade, 1.0); }'),
  show: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, '#version 300 es\nprecision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_tex;\nvoid main(){ vec3 c = texture(u_tex, v_uv).rgb; c = 1.0 - exp(-c * 1.5); c *= 1.0 - 0.3 * pow(length(v_uv - 0.5) * 1.4, 2.0); outColor = vec4(c + vec3(0.008, 0.009, 0.016), 1.0); }'),
  points: ctx.utils.createProgram('#version 300 es\nlayout(location=0) in vec2 a_position; layout(location=1) in float a_speed;\nout float v_speed; uniform float u_size;\nvoid main(){ v_speed = a_speed; gl_Position = vec4(a_position * 2.0 - 1.0, 0.0, 1.0); gl_PointSize = u_size; }', '#version 300 es\nprecision highp float; in float v_speed; out vec4 outColor; uniform vec3 u_calm; uniform vec3 u_gust;\nvoid main(){ float k = clamp(v_speed, 0.0, 1.0); outColor = vec4(mix(u_calm, u_gust, k) * mix(0.075, 0.2, k), 1.0); }'),
});

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const [w, h] = ctx.resolution;
if (!s.trails || s.size[0] !== w || s.size[1] !== h) {
  s.trails = ctx.utils.createPingPong(w, h, { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT, filter: gl.LINEAR });
  s.size = [w, h]; s.word = -1;
}
// Gusts come and go on their own (or hold Wind); each calm spells the next word.
const cycle = (ctx.time % 7) / 7;
const auto = cycle < 0.38 ? 1 : cycle < 0.5 ? 1 - (cycle - 0.38) / 0.12 : cycle < 0.9 ? 0 : (cycle - 0.9) / 0.1;
const target = u.u_auto ? Math.max(auto, ctx.mouseDown ? 1 : 0) : (ctx.mouseDown ? 1 : u.u_wind);
s.wind += (target - s.wind) * 0.06;
const word = u.u_auto ? Math.floor(ctx.time / 7) % s.WORDS.length : u.u_word;
if (word !== s.word) { s.word = word; s.targets = s.sample(s.WORDS[word], w, h); }
const aspect = w / h, t = ctx.time * 0.1, scale = u.u_scale, wind = s.wind;
for (let i = 0; i < s.N; i++) {
  const o = i * 3, v = i * 2;
  const x = s.pos[o], y = s.pos[o + 1];
  // Curl of the noise: a swirling wind that never piles particles into one stream.
  const px = x * scale * aspect, py = y * scale, e = 0.01;
  const fx = (s.noise(px, py + e, t) - s.noise(px, py - e, t)) / (2 * e);
  const fy = -(s.noise(px + e, py, t) - s.noise(px - e, py, t)) / (2 * e);
  // Flow-field push while it blows, a spring to the letter when it's calm.
  let vx = s.vel[v] + fx * 0.00045 * wind / aspect + (s.targets[v] - x) * 0.018 * (1 - wind) * u.u_pull;
  let vy = s.vel[v + 1] + fy * 0.00045 * wind + (s.targets[v + 1] - y) * 0.018 * (1 - wind) * u.u_pull;
  vx *= 0.9; vy *= 0.9;
  let nx = x + vx, ny = y + vy;
  if (nx < -0.05 || nx > 1.05 || ny < -0.05 || ny > 1.05) { nx = Math.random(); ny = Math.random(); vx = vy = 0; }
  s.vel[v] = vx; s.vel[v + 1] = vy;
  s.pos[o] = nx; s.pos[o + 1] = ny; s.pos[o + 2] = Math.min(1, Math.hypot(vx * aspect, vy) * 260);
}
ctx.publish("wind", Number(wind.toFixed(2)));
const read = s.trails.read(), write = s.trails.write();
gl.bindFramebuffer(gl.FRAMEBUFFER, write.framebuffer);
gl.viewport(0, 0, w, h);
gl.useProgram(s.fade);
ctx.utils.bindTexture(s.fade, "u_prev", read.texture, 0);
ctx.utils.drawFullscreen(s.fade, { u_fade: u.u_trail });
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
gl.useProgram(s.points);
ctx.utils.setUniforms(s.points, { u_calm: u.u_calm, u_gust: u.u_gust, u_size: Math.max(1.5, h / 700) });
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.buffer);
gl.bufferData(gl.ARRAY_BUFFER, s.pos, gl.DYNAMIC_DRAW);
gl.drawArrays(gl.POINTS, 0, s.N);
gl.bindVertexArray(null); gl.disable(gl.BLEND);
s.trails.swap();
gl.bindFramebuffer(gl.FRAMEBUFFER, null);
gl.viewport(0, 0, w, h);
gl.useProgram(s.show);
ctx.utils.bindTexture(s.show, "u_tex", s.trails.read().texture, 0);
ctx.utils.drawFullscreen(s.show);
